  ($j$carreras$j$, $j$Administración$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"","enfoque":"liderazgo, gestión estratégica y toma de decisiones","aprendera":"Recursos Humanos\nMarketing y ventas\nFinanzas y control\nEmprendimiento y gestión de proyectos\nEconomía empresarial y liderazgo","perfil":"lidera organizaciones con ética y visión estratégica","salidas":"gerencia, RRHH, marketing, consultoría, emprendimiento","notas":""}$j$::jsonb, true, 70),
  ($j$carreras$j$, $j$Contabilidad, Gestión Tributaria y Aduanera$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"","enfoque":"contabilidad, tributación y comercio exterior con integridad","aprendera":"Contabilidad financiera y de costos\nNIIF\nTributación empresarial y planeamiento tributario\nAuditoría financiera\nComercio exterior y legislación aduanera/tributaria","perfil":"gestiona información financiera y asesora con transparencia","salidas":"contabilidad corporativa, auditoría, consultoría tributaria, aduanas","notas":""}$j$::jsonb, true, 80),
  ($j$carreras$j$, $j$Derecho$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"12 semestres (6 años)","enfoque":"formación jurídica con ética cristiana y práctica progresiva","aprendera":"Derecho Civil y Comercial\nDerecho Penal (incluye litigación oral)\nConstitucional y Administrativo\nLaboral y Previsional\nInternacional y Aduanero\nAmbiental/Minero/Energético\nCosmovisión bíblica del Derecho y deontología jurídica","perfil":"abogado íntegro con capacidad de análisis, argumentación y servicio","salidas":"estudios jurídicos, Poder Judicial, Fiscalía, empresas, consultoría","notas":""}$j$::jsonb, true, 90),
  ($j$carreras$j$, $j$Psicología$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"","enfoque":"evaluación e intervención en salud mental con valores","aprendera":"Psicología del desarrollo\nPsicopatología\nPsicometría (evaluación)\nTerapia cognitivo-conductual\nNeuropsicología y psicología de la salud\nPsicología social","perfil":"evalúa, diagnostica e interviene con enfoque científico y humano","salidas":"clínica, educativa, organizacional, comunitaria, investigación","notas":""}$j$::jsonb, true, 100),
  ($j$carreras$j$, $j$Enfermería$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"","enfoque":"cuidado integral con base científica y humana","aprendera":"Anatomía y fisiología\nFundamentos de enfermería\nSalud pública y comunitaria\nCuidados por etapas de vida\nEmergencias y cuidados críticos\nInvestigación en salud + ética/bioética","perfil":"brinda atención integral y lidera servicios de salud","salidas":"hospitales, clínicas, comunidad, domicilio, gestión, docencia","notas":""}$j$::jsonb, true, 110),
  ($j$carreras$j$, $j$Nutrición Humana$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"","enfoque":"salud, prevención y tratamiento nutricional","aprendera":"Bioquímica y fisiología de la nutrición\nEvaluación del estado nutricional\nDietoterapia\nNutrición comunitaria\nMicrobiología de alimentos\nGestión de servicios de alimentación","perfil":"diseña planes nutricionales y promueve hábitos saludables","salidas":"clínica, salud pública, comedores, deporte, investigación","notas":""}$j$::jsonb, true, 120),
  ($j$carreras$j$, $j$Educación Inicial y Puericultura$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"","enfoque":"educación y cuidado integral de 0 a 5 años","aprendera":"Desarrollo infantil y psicología del niño\nDidáctica y metodologías de inicial\nNutrición, salud e higiene infantil\nEstimulación temprana\nAtención a la diversidad\nGestión de centros de educación infantil","perfil":"promueve desarrollo integral y guía a familias","salidas":"docencia inicial, estimulación temprana, gestión, consultoría","notas":""}$j$::jsonb, true, 130),
  ($j$carreras$j$, $j$Educación Primaria y Pedagogía Terapéutica$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"","enfoque":"primaria + atención educativa a NEE (inclusión)","aprendera":"Didáctica de primaria\nPsicopedagogía y desarrollo infantil\nAtención a la diversidad y didáctica inclusiva\nPedagogía terapéutica e intervención\nEvaluación psicopedagógica","perfil":"enseña y adapta metodologías para inclusión real","salidas":"primaria, educación inclusiva, centros especiales, asesoría","notas":""}$j$::jsonb, true, 140),
  ($j$carreras$j$, $j$Educación, Especialidad Lingüística e Inglés$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"","enfoque":"docencia bilingüe con metodologías innovadoras","aprendera":"Fonética y gramática avanzada (inglés/español)\nMetodología de enseñanza de idiomas\nDiseño curricular y evaluación\nDidáctica de lengua y literatura\nTecnología educativa aplicada a idiomas","perfil":"enseña con enfoque pedagógico, ético y multicultural","salidas":"docencia, institutos, materiales, consultoría, traducción","notas":""}$j$::jsonb, true, 150),
  ($j$carreras$j$, $j$Educación Física, Recreación y Deportes$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Vigente","duracion":"","enfoque":"","aprendera":"","perfil":"","salidas":"","notas":""}$j$::jsonb, true, 160),
