  ($j$carreras$j$, $j$Medicina Humana$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Nueva 2027-1","duracion":"","enfoque":"formación integral en salud, con sólida preparación científica y clínica, orientada a la atención del paciente, la prevención de enfermedades y el servicio a la comunidad.","aprendera":"Anatomía Humana\nFisiología\nBioquímica y Biología Molecular\nMicrobiología y Parasitología\nFarmacología\nPatología General y Clínica\nSemiología Médica\nDiagnóstico por Imágenes\nMedicina Interna\nCirugía General y Especializada\nPediatría y Gineco-Obstetricia","perfil":"médico/a con formación científica y clínica, capacidad para evaluar pacientes, interpretar signos y síntomas, establecer diagnósticos, brindar tratamiento y desarrollar acciones de prevención y promoción de la salud.","salidas":"centros de salud y hospitales, clínicas privadas, consultorios médicos, atención primaria y salud comunitaria, medicina ocupacional, programas de salud pública, investigación, docencia y especialización médica.","notas":"Inicia en la campaña 2027-1. Cuenta con CEPRE Medicina Verano 2027."}$j$::jsonb, true, 190),
  ($j$carreras$j$, $j$Tecnología Médica en Laboratorio Clínico y Anatomía Patológica$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Nueva 2027-1","duracion":"","enfoque":"formación especializada en diagnóstico de laboratorio, análisis clínico, anatomía patológica y apoyo a la investigación biomédica.","aprendera":"Anatomía, Fisiología y Bioquímica\nHematología y Bioquímica Clínica\nMicrobiología, Parasitología e Inmunología\nUroanálisis\nBanco de Sangre y Medicina Transfusional\nBiología Molecular y Genética\nAnatomía Patológica, Histotecnología y Citología\nControl de Calidad, Bioseguridad y Gestión de Laboratorio\nSalud Pública, Investigación y Ética","perfil":"profesional capacitado para realizar análisis de laboratorio, contribuir al diagnóstico y seguimiento de enfermedades, gestionar procesos de calidad y participar en investigación biomédica.","salidas":"laboratorios clínicos, bancos de sangre, servicios de anatomía patológica, laboratorios de biología molecular, instituciones de salud, control de calidad, investigación biomédica y vigilancia epidemiológica.","notas":""}$j$::jsonb, true, 200),
  ($j$carreras$j$, $j$Tecnología Médica en Terapia Física y Rehabilitación$j$, $j${"modalidad":"Presencial","sede":"Juliaca","estado":"Nueva 2027-1","duracion":"","enfoque":"formación especializada en evaluación, prevención, tratamiento y rehabilitación de alteraciones del movimiento y la función física.","aprendera":"Anatomía, Fisiología y Biomecánica\nKinesiología y Evaluación Funcional\nTerapia Manual\nAgentes Físicos: electroterapia, ultrasonido, láser y termoterapia\nEjercicio Terapéutico\nFisioterapia Musculoesquelética\nNeurorehabilitación\nRehabilitación Cardiopulmonar\nFisioterapia Pediátrica y Geriátrica\nFisioterapia Deportiva y Readaptación\nErgonomía y Salud Ocupacional\nInvestigación, Ética y Gestión","perfil":"profesional capacitado para evaluar, prevenir y tratar alteraciones del movimiento, contribuyendo a la recuperación funcional y calidad de vida de los pacientes.","salidas":"traumatología y ortopedia, neurología, rehabilitación cardiopulmonar, pediatría, geriatría, dolor crónico, fisioterapia deportiva, readaptación, rehabilitación domiciliaria, ergonomía y salud ocupacional, centros de rehabilitación, docencia, investigación.","notas":""}$j$::jsonb, true, 210),
  ($j$carreras$j$, $j$Administración (a distancia)$j$, $j${"modalidad":"A distancia","sede":"Lima","estado":"Vigente","duracion":"","enfoque":"liderazgo, gestión estratégica y toma de decisiones","aprendera":"Recursos Humanos\nMarketing y ventas\nFinanzas y control\nEmprendimiento y gestión de proyectos\nEconomía empresarial y liderazgo","perfil":"lidera organizaciones con ética y visión estratégica","salidas":"gerencia, RRHH, marketing, consultoría, emprendimiento","notas":"Se estudia a distancia; la sede es Lima. Mismo enfoque que la carrera presencial."}$j$::jsonb, true, 220),
